styles:
polygon {
  transform: scale(0.9);
  transform-origin: 50% 50%;
  transform-box: fill-box;
}

#knob {
  transition: transform 0.3s;
}

#knob:hover {
  fill: #222;
}

#knob:focus {
  outline: none;
  stroke: #4d90fe;
  stroke-width: 0.5;
}

.controls {
  opacity: 0;
  transition: opacity 0.3s;
  cursor: pointer;
}

#knob:focus ~ .controls,
#knob:hover ~ .controls {
  opacity: 1;
}

.controls:hover {
  opacity: 1;
}

.controls path {
  pointer-events: none;
}

.controls .region {
  pointer-events: fill;
  fill: none;
}

.controls .region:hover + path {
  fill: #fff;
}

.controls circle:hover {
  stroke: #fff;
}

.controls circle.pressed {
  fill: #fff;
}

text {
